require dirname(__DIR__).'/app/bootstrap.php';$u=current_user();if(!$u){header('Location: /login.php');exit;}$ref=(string)($_GET['ref']??'');if(!preg_match('/^TDC-[A-F0-9]{24}$/',$ref)){http_response_code(400);exit('Invalid payment reference.');}?>
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment status · TDC Tech</title><style>body{margin:0;background:#09090b;color:#f4f4f5;font:16px system-ui;display:grid;place-items:center;min-height:100vh}.box{max-width:480px;margin:24px;padding:32px;background:#171720;border:1px solid #ffffff1c;border-radius:18px}a{color:#a5b4fc}p{line-height:1.6;color:#c4c4cc}</style><main class="box"><h1>Checking your payment</h1><p id="state">We’re confirming your payment securely. This page will update automatically.</p><p><a href="/dashboard.php">Return to dashboard</a></p></main><script>const ref=<?=json_encode($ref)?>;async function check(){try{const r=await fetch('/api/payments/status.php?ref='+encodeURIComponent(ref),{credentials:'same-origin',cache:'no-store'});const d=await r.json();const el=document.getElementById('state');if(!r.ok)throw new Error(d.error||'Unable to check payment.');if(d.status==='completed'){el.textContent='Payment received. Your wallet is credited with £'+Number(d.amount).toFixed(2)+'.';return;}if(d.status==='failed'){el.textContent='Payment failed. No wallet credit was made.';return;}el.textContent='Payment status: '+d.status+'. We’ll keep checking…';}catch(e){document.getElementById('state').textContent=e.message;}setTimeout(check,5000);}check();</script></html>
